#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>

Adafruit_PWMServoDriver pwm;   // the board at its default address, 0x40

uint16_t ticksFor(int us) {
  return (uint32_t)us * 4096 / 20000;
}

void send(uint8_t ch, int us) {
  uint16_t off = ticksFor(us);
  pwm.setPWM(ch, 0, off);   // on at tick 0, off at tick off
  Serial.print("ch");
  Serial.print(ch);
  Serial.print(" ");
  Serial.print(us);
  Serial.print(" us = ");
  Serial.print(off);
  Serial.println(" ticks");
}

void setup() {
  Serial.begin(9600);
  pwm.begin();
  pwm.setPWMFreq(50);
  send(0, 1500);
  send(1, 600);
  send(2, 2400);
}

void loop() {}

